define(["jquery"],function($){"use strict";function getString(key,fallback){var component="proctoringpolicy_password";try{if(window.M&&window.M.util&&window.M.util.get_string){return window.M.util.get_string(key,component)}}catch(e){}return fallback||""}function buildBrowserInfo(){var info={userAgent:navigator.userAgent||"",platform:navigator.platform||"",language:navigator.language||"",screen:String(screen.width)+"x"+String(screen.height),timezoneOffset:(new Date).getTimezoneOffset()};return JSON.stringify(info)}function postAjax(url,data){return $.ajax({url:url,method:"POST",dataType:"json",data:data})}function init(ctx,cfg){if(!cfg){return}var cmid=Number(ctx.cmid||0);var attemptid=Number(ctx.attemptid||0);var $container=$('[data-kppass="container"]');if($container.length===0){return}var $status=$container.find('[data-kppass="status"]');var $btnRequest=$container.find('[data-kppass="request"]');var $inputPassword=$container.find('[data-kppass="password"]');var $btnSubmit=$container.find('[data-kppass="submit"]');var polling=null;function setStatus(text){$status.text(text||"")}function handleStatusResponse(resp){if(!resp||!resp.status){return}if(resp.status==="pending"){setStatus(getString("js_status_pending","Request sent. Waiting approval."))}else if(resp.status==="approved"){setStatus(getString("js_status_approved","Approved. You can start the exam."));var ev=new CustomEvent("kopere_proctoring_password_authorized",{detail:{cmid:cmid,attemptid:attemptid}});window.dispatchEvent(ev);if(polling){window.clearInterval(polling);polling=null}}else if(resp.status==="blocked"){setStatus(getString("js_status_blocked","You are temporarily blocked."));if(polling){window.clearInterval(polling);polling=null}}}function startPolling(){if(polling){return}polling=window.setInterval(function(){postAjax(`${M.cfg.wwwroot}/local/kopere_proctoring/policy/password/ajax.php`,{action:"check",cmid:cmid,attemptid:attemptid}).done(function(r){handleStatusResponse(r)})},5e3)}$btnRequest.on("click",function(){setStatus(getString("js_status_waiting","Waiting for teacher approval..."));postAjax(`${M.cfg.wwwroot}/local/kopere_proctoring/policy/password/ajax.php`,{action:"request",cmid:cmid,attemptid:attemptid,browserinfo:buildBrowserInfo()}).done(function(resp){if(resp&&resp.error==="blocked"){setStatus(getString("js_toomany_errors","Too many wrong attempts. Please wait 10 minutes."));return}setStatus(getString("js_status_waiting","Waiting for teacher approval..."));startPolling()})});$btnSubmit.on("click",function(){var code=($inputPassword.val()||"").replace(/\D/g,"");if(code.length!==8){setStatus(getString("js_wrong_password","Invalid password."));return}postAjax(`${M.cfg.wwwroot}/local/kopere_proctoring/policy/password/ajax.php`,{action:"submitcode",cmid:cmid,attemptid:attemptid,code:code}).done(function(resp){if(!resp){return}if(resp.error==="blocked"){setStatus(getString("js_toomany_errors","Too many wrong attempts. Please wait 10 minutes."));return}if(resp.error==="wrong"){setStatus(getString("js_wrong_password","Invalid password."));return}if(resp.status==="approved"){handleStatusResponse(resp)}})})}return{init:init}});